<section class="mb-6"><h1 class="text-2xl font-bold text-slate-900">Riwayat Aktivitas</h1><p class="mt-1 text-sm text-slate-500">Pantau setiap perubahan data yang dilakukan oleh staff.</p></section>
<section class="rounded-2xl bg-white p-4 shadow-card sm:p-6"><form class="grid gap-3 md:grid-cols-[1fr_180px_auto]" method="get"><label class="sr-only" for="q">Cari aktivitas</label><div class="relative"><span class="absolute left-3 top-3 text-slate-400">⌕</span><input id="q" name="q" value="<?= e($search) ?>" class="form-input pl-9" placeholder="Cari nama staff, detail, atau referensi"></div><select name="modul" class="form-input"><option value="">Semua modul</option><?php foreach (['Pelanggan','Tagihan','Pemutusan','Daftar Ulang','User'] as $option): ?><option value="<?= e($option) ?>" <?= $modul === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select><div class="flex gap-2"><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white hover:bg-primary-dark">Cari</button><a href="<?= e(url('/riwayat-aktivitas')) ?>" class="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-600 hover:bg-slate-50">Reset</a></div></form>
    <div class="mt-6 overflow-hidden rounded-xl border border-slate-100"><?php if ($data['rows']): ?><div class="table-wrap"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">Waktu</th><th class="px-5 py-3">Staff</th><th class="px-5 py-3">Aksi</th><th class="px-5 py-3">Modul</th><th class="px-5 py-3">Referensi</th><th class="px-5 py-3">Detail</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($data['rows'] as $row): $aksiClass = ['Tambah' => 'disetujui', 'Ubah' => 'pending', 'Hapus' => 'ditolak'][$row['aksi']] ?? 'neutral'; ?><tr class="hover:bg-slate-50/70"><td class="px-5 py-4 text-slate-500 whitespace-nowrap"><?= e(formatTanggalWaktu($row['created_at'])) ?></td><td class="px-5 py-4"><div class="flex items-center gap-2"><div class="flex h-7 w-7 items-center justify-center rounded-full bg-blue-100 text-xs font-bold text-primary"><?= e(strtoupper(substr($row['nama_lengkap'], 0, 1))) ?></div><div><p class="font-semibold text-slate-800"><?= e($row['nama_lengkap']) ?></p><p class="text-xs text-slate-500"><?= e($row['username']) ?></p></div></div></td><td class="px-5 py-4"><span class="badge badge-<?= $aksiClass ?>"><?= e($row['aksi']) ?></span></td><td class="px-5 py-4 text-slate-600"><?= e($row['modul']) ?></td><td class="px-5 py-4 font-mono text-xs font-semibold text-primary"><?= e($row['referensi'] ?: '—') ?></td><td class="px-5 py-4 text-slate-600 max-w-xs truncate" title="<?= e($row['detail']) ?>"><?= e($row['detail']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: $emptyTitle='Belum ada riwayat aktivitas'; $emptyText='Aktivitas perubahan data oleh staff akan tercatat di sini secara otomatis.'; require root_path('app/Views/components/empty-state.php'); endif; ?></div><?php require root_path('app/Views/components/pagination.php'); ?></section>
